// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint128 reserves, uint16 feeRate, uint56 changeFee) public {
        vm.assume(feeRate <= 5000);
        vm.assume(reserves > 0);
        try c.initialize(address(0), address(0), reserves, reserves, changeFee, feeRate, bytes32(0), false, false) {
            assertTrue(c.initialized());
        } catch {
            assertTrue(!c.initialized());
        }
    }
}
